### 7. Test MockEl pattern — ✅ MATCHES

**Existing `MockEl` interface** (`src/__tests__/views/snippet-tree-picker.test.ts:30-72`): A hand-rolled interface defining every DOM method the picker calls, plus a `makeEl()` factory (:75-215) returning a concrete object implementing each member.

**Four new methods** — confirmed present in BOTH the interface and the factory, added additively (no existing member removed or rewritten):

**Interface additions** (`:69-72`, placed after `dispatchEvent` and before `remove`):
```ts
  querySelector: (selector: string) => MockEl | null;
  querySelectorAll: (selector: string) => MockEl[];
  scrollIntoView: (opts?: unknown) => void;
  click: () => void;
```

**Factory implementations** (`:141-173`, placed after `dispatchEvent` implementation and before `remove`):
```ts
    querySelector(selector: string): MockEl | null {
      // Minimal: supports a single '.class' selector. Returns first descendant
      // match in document order (mirrors DOM querySelector semantics — not self).
      const cls = selector.trim().startsWith('.') ? selector.trim().slice(1) : selector.trim();
      function walk(node: MockEl): MockEl | null {
        for (const c of node.children) {
          if (c.classList.has(cls)) return c;
          const r = walk(c);
          if (r) return r;
        }
        return null;
      }
      return walk(el);
    },
    querySelectorAll(selector: string): MockEl[] {
      // Minimal: supports comma-separated '.class1, .class2' selectors. ...
      const classes = selector.split(',').map((s) => s.trim()).filter((s) => s.startsWith('.')).map((s) => s.slice(1));
      const out: MockEl[] = [];
      function walk(node: MockEl): void {
        for (const c of node.children) {
          if (classes.some((cls) => c.classList.has(cls))) out.push(c);
          walk(c);
        }
      }
      walk(el);
      return out;
    },
    scrollIntoView(_opts?: unknown): void {},
    click(): void {
      el.dispatchEvent({ type: 'click', target: el });
    },
```

These are purely additive — all pre-existing members (`createEl`, `createDiv`, `createSpan`, `empty`, `setText`, `appendChild`, `addClass`, `removeClass`, `setAttribute`, `getAttribute`, `addEventListener`, `removeEventListener`, `dispatchEvent`, `remove`, `focus`) are unchanged.

